// src/services/chatService.js
const API_URL = 'http://localhost:5000/api';

export const chatService = {
  // Conversations
  getConversations: async (token) => {
    const response = await fetch(`${API_URL}/conversations`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    return response.json();
  },

  getConversation: async (id, token) => {
    const response = await fetch(`${API_URL}/conversations/${id}`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    return response.json();
  },

  createConversation: async (data, token) => {
    const response = await fetch(`${API_URL}/conversations`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify(data)
    });
    return response.json();
  },

  // Messages
  getMessages: async (conversationId, token) => {
    const response = await fetch(`${API_URL}/conversations/${conversationId}/messages`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    return response.json();
  },

  sendMessage: async (conversationId, message, token) => {
    const response = await fetch(`${API_URL}/conversations/${conversationId}/messages`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify(message)
    });
    return response.json();
  },

  markAsRead: async (conversationId, token) => {
    const response = await fetch(`${API_URL}/conversations/${conversationId}/read`, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}` }
    });
    return response.json();
  }
};
